actions.script:
const FIELDS = ['emailAccountId', 'emailFolderId', 'rootEmailMessageId', 'statusId', 'isRead', 'isFlagged', 'isAnswered',
    'archivedDate', 'snoozedThruDate', 'messageDate', 'sendError', 'scheduledSendDate', 'hasAttachment', 'subject', 'snippet']
const norm = (value) => value == null || value === '' ? '' : (typeof value === 'object' && typeof value.getTime === 'function'
    ? String(value.getTime()) : String(value))
const pick = (value) => {
    if (value == null) return null
    const picked = {}
    for (const name of FIELDS) picked[name] = value[name] == null || value[name] === '' ? null : norm(value[name])
    return picked
}
const operation = String(eecaOperation)
const prior = typeof originalValue === 'undefined' ? null : originalValue
const before = operation === 'create' ? null : pick(prior)
const after = operation === 'delete' ? null : pick(entityValue)
const id = (entityValue && entityValue.emailMessageId) || (prior && prior.emailMessageId) || null
const changed = !before || !after || FIELDS.some((name) => before[name] !== after[name])
if (id && changed && ((before && before.emailAccountId) || (after && after.emailAccountId))) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.mail.EmailClientServices.note#MessageChange').parameters({emailMessageId: id,
            operation: operation, before: before, after: after}).disableAuthz().call()
        if (ec.message.hasError()) ec.logger.error(`The mail change of message ${id} is not noted: ${ec.message.errorsString}`)
    } catch (err) {
        ec.logger.error(`The mail change of message ${id} is not noted: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

const id = (entityValue && entityValue.emailMessageId) || null
if (id) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.mail.EmailClientServices.note#MessageChange').parameters({emailMessageId: id,
            operation: 'related'}).disableAuthz().call()
    } catch (err) {
        ec.logger.error(`The label change of message ${id} is not noted: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

const id = (entityValue && entityValue.emailMessageId) || null
if (id) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.mail.EmailClientServices.note#MessageChange').parameters({emailMessageId: id,
            operation: 'related'}).disableAuthz().call()
    } catch (err) {
        ec.logger.error(`The attachment change of message ${id} is not noted: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
